import React, { useState } from 'react';
import './App.css';
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min";

function App() {
  const [userName, setUserName] = useState("");
  const [pwd, setPwd] = useState("");
  const [isLoginForm, setIsLoginForm] = useState(true);  // State to toggle forms
  const [value, setValue] = useState("");

  // Handle form submission for Login and Register
  const update = () => {
    if (isLoginForm) {
      if (userName !== "" && pwd !== "" && userName === "admin" && pwd === "admin123") {
        alert("Login Success");
      } else {
        alert("Login Failed");
      }
    } else {
      alert("Sign Up logic is not implemented yet!");
    }
  };

  // Toggle form between Login and Register
  const toggleForm = () => {
    setIsLoginForm(!isLoginForm);  // Toggle between login and register forms
  };

  return (
    <div className='form-container'>
      <div className='col col-2'>
        <div className='btn-box'>
          <button className='btn btn-1' onClick={toggleForm}>Sign In</button>
          <button className='btn btn-2' onClick={toggleForm}>Sign Up</button>
        </div>
      </div>
      <div className='container'>
        <form onSubmit={update}>
          {/* Login Form */}
          {isLoginForm ? (
            <div className='login-form'>
              <div className='form-title'>
                <span>Sign In</span>
              </div>
              <div className='form-inputs'>
                <div className='input-box'>
                  <input type="text" className="input-field" onChange={(e) => setUserName(e.target.value)} placeholder='Username' required />
                  <i className='bx bx-user-alt icon'></i>
                </div>
                <div className='input-box'>
                  <input type="password" className="input-field" onChange={(e) => setPwd(e.target.value)} placeholder='Password' required />
                  <i className='bx bx-lock-alt icon'></i>
                </div>
                <div className="forget-pass">
                  <a href="/recover-password">Forget Password</a>
                </div>
                <div className='input-box'>
                  <button className='input-submit'>
                    <span>Sign In</span>
                    <i className='bx bx-right-arror-alt'></i>
                  </button>
                </div>
              </div>
            </div>
          ) : (
            /* Register Form */
            <div className='register-form'>
              <div className='form-title'>
                <span>Create Account</span>
              </div>
              <div className='form-inputs'>
                <div className='input-box'>
                  <input type="email" className="input-field" placeholder='Email' required />
                  <i className='bx bx-envelope-alt icon'></i>
                </div>
                <div className='input-box'>
                  <input type="text" className="input-field" placeholder='Username' required />
                  <i className='bx bx-user-alt icon'></i>
                </div>
                <div className='input-box'>
                  <input type="password" className="input-field" placeholder='Password' required />
                  <i className='bx bx-lock-alt icon'></i>
                </div>
                <div className="forget-pass">
                  <a href="/recover-password">Forget Password</a>
                </div>
                <div className='input-box'>
                  <button className='input-submit'>
                    <span>Sign Up</span>
                    <i className='bx bx-right-arror-alt'></i>
                  </button>
                </div>
              </div>
            </div>
          )}
          <input type="submit" style={{ display: 'none' }} />
        </form>
      </div>
    </div>
  );
}

export default App;
